exec((__import__('pathlib').Path(__file__).parent/'mulanhua_a.py').read_text(encoding='utf-8').split("B('01巧夺死光表'")[0])
B('04木雕人头',[
C('pederson','彼德逊','彼德逊是西方某国特务部门的军官，为追索战争末期的海底火龙计划来到木兰花所在的城市。他借国际警方的协助，以高级警务人员的身份接近姐妹，却把协助关系说成自己的正式身份，强行取走藏有密码的木雕人头，并试图迫使木兰花合作。这种急于掌握主导权的做法反而使双方互设防备，木兰花从他的行李入手，自行追到南洋的海底基地；他仍须依赖自己的情报系统、当地警方与飞机搜索，没能单凭机构权力取得全部秘密。再见时，木兰花已经制服以凶狠著名的石头，他不得不承认先前低估了她，将威胁式的合作要求改成诚恳求助，并用生硬中文向穆秀珍道歉。他准确判断犯罪集团宁愿交出委托人也不愿正面得罪警方，以石头换来石川虎山，取得另一半密码；随后携潜水装备跟木兰花入库，重视的已经不是陈旧武器本身，而是仍有研究价值的固体燃料。事件之后他支付报酬，双方建立合作关系。二十三册围剿ＫＩＤ总部时，木兰花在监控中认出他实际参与行动，合作已经延续。这个人物能改变态度，却不会因此失去情报人员的试探习惯；国别利益、情报来源和警方许可都是他行动的实际条件。','04完成海底火龙情报任务并与姐妹化敌为友；23实际参与ＫＩＤ总部围剿，未写死亡。','外国男子，工作时习惯试探与质问；道歉时认真使用生硬中文。','为所属国家取得有价值的技术情报，必要时维护有效合作。','先借机构优势要求服从；受挫后能够承认错误并交换情报。','特务情报调查、与警方协调、装备潜水和交易判断；科研秘密不等于个人能制造武器。',[(1430,1438,'真实身份、先前对抗及转为合作'),(1464,1468,'交换人质和道歉'),(1484,1504,'潜水取证与燃料秘密'),('木兰花全集/23大破暗杀党.txt',2524,2524,'实际参与总部围剿')],[('民间调查者掌握关键部分','强令合作曾经失败','改以交换信息和承认贡献争取帮助。'),('犯罪集团有可交换的重要人手','自己可协调警方谈判','计算对方利益，用交换减少正面冲突。'),('找到过时装备','其中仍有未知技术','区分装备战斗价值与研究价值，不因外观陈旧放弃检查。')],roles=['重要配角','阶段性对立者'],aliases=['彼得逊'],scores=GUN,tier='并',uncertainties=['11仅被上司提及而非实际出场；23参加国际协作不证明其由本国特务改任国际警察。']),
C('ishikawa_torayama','石川虎山','石川虎山曾与另外三名希特勒近卫队员奉命到远东为秘密武器研究者授勋，战败将近时，他们却杀死基地中的科学家，把武器库关闭，打算多年之后把技术卖给出价最高的国家。他作为东方人保管六只藏有密码碎片的木人头，后来起意独吞，偏偏木人头被普通窃贼偷走，辗转落到穆秀珍手中，宏大谋算因此被一件偶然买卖打乱。他一面登门试探木兰花，一面与旧同伙争夺和追踪；抢夺中又以毒刺杀死同行者，试图把共谋变成只有自己知道的秘密。失去全部密码后，他求助于南洋犯罪集团，把海底火龙的巨大利益作为报酬前景，却没有掌握足够力量约束所委托的罪犯。木兰花制服石头，彼德逊提议交换，集团便毫不迟疑地出卖石川。他被捆送到警方艇上，知道局面已无从挽回，终于供出另一半密码。人物的结局重演了他自己奉行的利益逻辑：同谋可以随时被牺牲，强势合作者也不会替他守信。其危险在刀枪、近身格斗、毒刺和隐瞒信息，不能把参与夺取研究成果写成亲自发明海底武器。','遭受委托的犯罪集团出卖，被交给警方一方，供出剩余密码；后续审判未写。','日本男子，能作客气交谈，动手时凶狠；真实年龄未固定。','独占海底火龙秘密，换取巨额财富。','表面合作，掌握机会便清除同伙；失势后转求更强组织。','近身格斗、手枪与吹射毒刺、保管密码；毒性按故事事件存在，不扩写为全能毒术。',[(450,508,'上门试探与冲突'),(792,876,'同伙夺物、毒刺及独吞'),(1442,1460,'历史共谋'),(1466,1484,'被出卖与交出密码')],[('共同秘密可换大笔财富','认为同伙已可替代','可能暗中准备独吞而破坏合作。'),('自己无法压服持有线索者','有更大犯罪组织可接触','以未来分利换取武装协助。'),('受托者反过来出卖自己','已失去人手和谈判条件','承认失败并交出自己保有的部分。')],roles=['反派'],scores={**GUN,'combat':4},tier='并'),
C('fire_dragon_old_guards','海底火龙计划的三名旧近卫同伙','这三名没有留下姓名的旧近卫队员，与石川虎山共同到过海底火龙基地，也共同参与杀害科学家、封存武器和日后出售秘密的计划。他们并非研究者，而是把战败时接近机密的职务转成私人财产的人。密码被分藏在六只木人头里，由石川保管，看似避免分散失落，却使其余人长期依赖一个有独吞念头的同伙。木人头流到穆秀珍家之后，其中的独脚人反复窥视，行动虽敏捷，仍在街上遭毒刺杀死，身上的残纸与刺青成为木兰花追查的入口。其余二人在花园夺物时现身，一个身有旧近卫身份的刺青，另一个以吹刺袭击；他们既要对付姐妹，也没有防住石川在争夺中进一步灭口，最终同样倒在毒刺之下。三人的共同身份和合作历史明确，个人姓名、完整履历与彼此内心差异则没有材料，因而按这次共同阴谋记录，不把三个身体合并成一个可同时使用所有招式的超人。回溯参战时要分别保留独脚人的肢体限制和各成员实际装备，不能因死于毒物便推断他们生前拥有抗毒能力或无限暗器。','三人均在木雕密码争夺中死于毒刺；其中两人的死亡由石川当场背叛造成。','一名独脚人、一名带近卫身份刺青者及一名非洲人；无可靠姓名。','找回共同隐藏的密码，出售旧武器秘密获利。','秘密跟踪和合力夺物，但合作中的背叛风险未受控制。','有限的跟踪、格斗及其中一人的吹刺手段；按多人共同条目部署，不叠加身体。',[(32,106,'独脚人的窥视、死亡和残纸'),(792,856,'后两人夺物与死亡'),(1442,1460,'四人共谋历史')],[('多年隐藏的财产突然流入陌生人手中','确认目标确实持有线索','反复跟踪而不轻易放弃。'),('夺物需要多人合作','仍认为共同利益足以维持同盟','可能忽视保管者的独吞打算。'),('已有成员受伤或残疾','行动仍有必要','依赖器械与配合补足，不抹去身体限制。')],roles=['反派'],scores={'physical':2,'energy':0,'scope':0,'sustain':2,'range':1,'combat':3},tier='并',revive=True),
C('stone','石头','石头是南洋犯罪集团大头子的得力部下，外号来自冷硬得没有感情的声音与表情。他乘水上飞机追到姐妹藏身的孤岛，接走从艇上逃来的同党，认定她们的潜水氧气不能久用，便以机枪压制、扩音喊话和登岛搜索逼迫投降。部下在近距离搜索中被木兰花夺枪，他仍倚赖飞机上的重武器，从空中发射毒气，把姐妹逼出岩洞与海岸，再用飞机冲向水面的人。这些手段使环境本身成为围困的一部分，却也让他相信对方只有逃命，没有反攻的路径。木兰花攀上飞机，在近身搏斗中击昏他，穆秀珍又迫使驾驶者降服；冷硬外貌不能防住实在的撞击，也掩不住被制住后对搔痒的反应。随后他被警方控制，大头子因为重视他的用处，同意拿石川虎山交换他与机枪手，石头因此未在本篇受到最终审判。人物参战须有实在可调动的飞机、弹药与驾驶同伴，不能把一次组织空袭写成随手召唤；神情不变也不是精神免疫，只是一种给人压力的行为方式。','被木兰花制服交给警方一方，随后与机枪手一并作为交换条件释放给犯罪集团。','黑衣瘦男子，声音平板冷硬，表情很少变化。','执行集团夺密任务，靠优势装备压服危险目标。','逐步剥夺掩蔽和退路，以武装威胁催促投降。','组织配给的机枪、毒气弹和水上飞机协同；个人近身行动仍可被制服。',[(1250,1268,'接应同党及飞机追击'),(1296,1336,'逼降、搜索和毒气'),(1340,1418,'飞机攻击、被制与供述'),(1466,1484,'交换释放')],[('对手依赖有限氧气或狭小掩蔽','自己控制外围','先等待消耗，再用武器迫其现身。'),('部下近距离搜索失败','仍有携带的范围武器','升级压制手段，但可能毁掉可谈判的余地。'),('看似无路的敌人贴近载具','自己只防远处逃跑','会暴露近身防护不足，外表冷静不能抵消这一点。')],roles=['反派'],scores={'physical':2,'energy':1,'scope':2,'sustain':2,'range':3,'combat':4},tier='并'),
C('yacht_hidden_traitor','游艇上杀害同伴的潜伏者','这名潜伏者受犯罪集团指派，与另一人藏在卖给计镇江的游艇暗格里，原本要查富豪深夜购买高速艇的原因。木兰花与穆秀珍借艇出海，反让他接触到海底火龙线索；他想私吞所得，同伴不肯配合并扬言报告，他便从背后开枪杀人。木兰花制住他后，他先假装失去反抗能力，又拔枪试图反击；武器被踢飞后，才透露例行通讯与远程炸艇安排，用组织的后手保护自己。收到上级追捕姐妹的命令，他随即变成热切谈合作的人，答应提供秘密来换好处，口头声称愿意改邪归正，实际寻找脱身机会。讲到要紧处，他用叫喊引人转头，启动画后藏着的毒刺机关，再从窗口跳海，获石头的飞机接走后又把同伴之死栽给木兰花。岛上围捕时，他持机枪从高处企图射击，木兰花听见机件声音先开火，他中弹倒落。这个人一次又一次把承诺当争取动作时间的工具，但他的每次背叛都需要现成枪械、机关或接应，绝非随意摆脱控制的超能力。','在孤岛高处企图用机枪袭击木兰花时中弹倒落；随后对话以死亡相称。','无姓名男子，擅作狡猾笑容，处于弱势时会涎脸求分利。','夺取秘密独吞好处，失败时保命并推卸责任。','假昏、假合作、转移注意，然后借预设机关脱身。','枪械、暗舱通讯、现成发刺机关及游泳；无自主远程炸艇权限证据。',[(1118,1156,'杀同伴、假昏反击及远程爆炸威胁'),(1160,1190,'通讯、诱骗、发刺和逃海'),(1252,1260,'接应与栽赃'),(1324,1332,'中弹结局')],[('同伙拒绝私分秘密并准备报告','自己有隐蔽先手机会','可能直接杀人切断举报。'),('被制住但现场仍有预设器械','对方愿听供述','以合作和悔改争取接近开关的时间。'),('获己方接应','自己曾损害组织利益','先把损失归罪于敌方，以便重新参与追捕。')],roles=['反派'],scores=GUN,tier='并',revive=True,uncertainties=['通讯同时报十三号、十七号，原文不足以把其中一个编号唯一对应此人。']),
C('gold_mast_boss','金桅杆号的大头子','大头子是南洋一个庞大犯罪集团的神秘首脑，组织既从事各种非法交易，也接受过国家情报部门的雇用。石川虎山带着海底火龙的秘密向他求助，他的部下又从计镇江的购艇要求发现机会，于是在游艇中安排潜伏与通讯控制，让普通买卖变成监视和夺密的入口。遇到木兰花姐妹，集团接连调动飞机、枪手与毒气执行追捕，显示其危险主要来自组织准备，不来自首脑本人公开展示的格斗。木兰花制服石头之后，彼德逊判断他不会为了委托人正面与当地警方冲突，果然一经联系，他就答应拿石川交换自己的得力部下。豪华游艇金桅杆号来到约定海面，双方保持距离，由水手完成交人；大头子没有露出可核验的面貌，本地警官只是根据专用艇推断他亲自到来。他救回石头与机枪手后离去，把刚刚收下的委托人彻底放弃。这个决定比神秘排场更能说明其逻辑：保留长期有用的组织资产，远比遵守一笔新委托重要。艇能迅速变成炮艇只是人物转述，不能当作已演示性能，更不能折算成首脑肉身的破坏力。','完成换人后金桅杆号离去，未被捕；首脑是否本人在艇上仍属当地警方推断。','没有可靠正面外貌，身份以专用豪华艇与组织指令辨认。','保护组织和得力人员，在秘密交易中获利并避免不利的正面冲突。','通过下属行动；交易风险改变后可以立即出卖委托人。','组织情报、潜伏安排及利益交换；调用武装需要具体人员、装备和传令链。',[(1164,1180,'组织指令、委托与潜伏艇'),(1466,1484,'换人决策、神秘身份及离去')],[('委托报酬巨大但强敌介入','继续履约会损害已有组织','会重估交易，甚至把委托人当交换物。'),('得力执行者被敌方扣住','可以用别的资产换回','优先保全长期合作的人手。'),('谈判必须在公开可观察处进行','担心靠近遭控制','保持距离，派中间人完成交割。')],roles=['反派'],limits='未展示个人战斗，评级仅按普通肉身；武装组织是条件性资源。金桅杆号变炮艇是传闻，不作确定能力。',uncertainties=['首脑无姓名与正面出场；不擅自与其他书的犯罪首领合并。'])],cast=['mu_lanhua','mu_xiuzhen','gao_xiang','fang_director'],excluded=[{'name':'计镇江、莎莎夫人','reason':'一次性友人供艇及误取箱子的旁观者，没有独立主角线或反派行为。'},{'name':'阿二、石头的机师和机枪手','reason':'一次性执行助手；已在主要人物的条件性支援和事件证据内记载，不据零散行动虚构独立经历。'}],notes=['海底火龙旧武器属于争夺标的，研究燃料的价值不赋予任何人物制造能力。'])
(P/'mulanhua_c.draft.json').write_text(json.dumps(books,ensure_ascii=False,indent=2),encoding='utf-8')
